// Bundled datapacks: FILES is generated by xtask from our templates/assets.
use std::fs;
use std::io::{self, Write};
use std::path::Path;

pub const GAMEPLAY: &str = "Litospherity - Игровой мир";
pub const SCIENTIFIC: &str = "Litospherity - Научный мир";

/// Install missing packs into the new world's temporary directory. Never
/// overwrite an existing pack: re-created worlds must keep their old version.
pub fn install(dir: &Path) -> io::Result<()> {
    fs::create_dir_all(dir)?;
    for name in [GAMEPLAY, SCIENTIFIC] {
        let destination = dir.join(name);
        if destination.exists() {
            continue;
        }
        let staging = dir.join(format!(".{name}.installing"));
        if staging.exists() {
            fs::remove_dir_all(&staging)?;
        }
        fs::create_dir(&staging)?;
        let result = (|| {
            for &(pack, relative, bytes) in FILES {
                if pack != name {
                    continue;
                }
                let path = staging.join(relative);
                if let Some(parent) = path.parent() {
                    fs::create_dir_all(parent)?;
                }
                let mut file = fs::File::create(&path)?;
                file.write_all(bytes)?;
            }
            fs::rename(&staging, &destination)
        })();
        if result.is_err() {
            let _ = fs::remove_dir_all(&staging);
        }
        result?;
    }
    Ok(())
}

pub fn conflicting(selected: &[String]) -> bool {
    let has = |name: &str, legacy: &str| {
        selected.iter().any(|id| {
            id == &format!("file/{name}")
                || id == &format!("file/{legacy}")
                || id == &format!("file/{legacy}.zip")
        })
    };
    has(GAMEPLAY, "litospherity_v0_gameplay") && has(SCIENTIFIC, "litospherity_v0_scientific")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn installs_only_two_modes_and_never_overwrites() {
        let dir = std::env::temp_dir().join(format!("litho-packs-test-{}", std::process::id()));
        let _ = fs::remove_dir_all(&dir);
        install(&dir).unwrap();
        assert_eq!(fs::read_dir(&dir).unwrap().count(), 2);
        for name in [GAMEPLAY, SCIENTIFIC] {
            assert!(dir.join(name).join("pack.png").is_file());
            assert!(dir.join(name).join("pack.mcmeta").is_file());
        }
        let sentinel = dir.join(GAMEPLAY).join("pack.mcmeta");
        fs::write(&sentinel, b"keep my saved pack").unwrap();
        install(&dir).unwrap();
        assert_eq!(fs::read(&sentinel).unwrap(), b"keep my saved pack");
        fs::remove_dir_all(dir).unwrap();
    }

    #[test]
    fn rejects_mixed_modes_including_legacy_archives() {
        assert!(!conflicting(&[
            "vanilla".into(),
            format!("file/{GAMEPLAY}")
        ]));
        assert!(conflicting(&[
            format!("file/{GAMEPLAY}"),
            "file/litospherity_v0_scientific.zip".into(),
        ]));
    }
}
